     2	
     3	import br.com.marealta.domain.Formats;
     4	import br.com.marealta.domain.Reservation;
     5	
     6	/** Avisa o financeiro dos pagamentos recebidos e dos reembolsos a fazer. */
     7	public class FinanceNotifier implements ReservationListener {
     8	    static final String ADDRESS = "financeiro@pousadamarealta.com.br";
     9	
    10	    private final MessageSender sender;
    11	
    12	    public FinanceNotifier(MessageSender sender) {
    13	        this.sender = sender;
    14	    }
    15	
    16	    @Override
    17	    public void on(ReservationEvent event) {
    18	        switch (event) {
    19	            case ReservationEvent.Confirmed confirmed -> {
    20	                Reservation r = confirmed.reservation();
    21	                sender.email(ADDRESS, "Pagamento recebido - reserva " + r.id(),
    22	                        "Pagamento recebido da reserva %d: %s.".formatted(r.id(), Formats.money(r.amountPaid())));
    23	            }
    24	            case ReservationEvent.Cancelled cancelled when cancelled.reservation().refund().signum() > 0 -> {
    25	                Reservation r = cancelled.reservation();
    26	                sender.email(ADDRESS, "Reembolso - reserva " + r.id(),
    27	                        "Reserva %d cancelada. Valor a devolver ao hóspede: %s.".formatted(
    28	                                r.id(), Formats.money(r.refund())));
    29	            }
    30	            default -> {
    31	            }
    32	        }
    33	    }
