     7	/** Avisa a governança para preparar o quarto, ou que ele ficou livre. */
     8	public class HousekeepingNotifier implements ReservationListener {
     9	    static final String ADDRESS = "governanca@pousadamarealta.com.br";
    10	
    11	    private final MessageSender sender;
    12	
    13	    public HousekeepingNotifier(MessageSender sender) {
    14	        this.sender = sender;
    15	    }
    16	
    17	    @Override
    18	    public void on(ReservationEvent event) {
    19	        switch (event) {
    20	            case ReservationEvent.Confirmed confirmed -> {
    21	                Reservation r = confirmed.reservation();
    22	                sender.email(ADDRESS, "Reserva confirmada - quarto " + r.room().number(), """
    23	                        Reserva %d confirmada para o quarto %d.
    24	
    25	                        Entrada: %s
    26	                        Saída: %s
    27	                        Hóspedes: %d""".formatted(r.id(), r.room().number(),
    28	                        Formats.date(r.checkInDate()), Formats.date(r.checkOutDate()), r.guests()));
    29	            }
    30	            case ReservationEvent.Cancelled cancelled
    31	                    when cancelled.previousStatus() == ReservationStatus.CONFIRMED -> {
    32	                Reservation r = cancelled.reservation();
    33	                sender.email(ADDRESS, "Reserva cancelada - quarto " + r.room().number(), """
    34	                        Reserva %d cancelada. O quarto %d ficou livre nas datas:
    35	
    36	                        Entrada: %s
    37	                        Saída: %s""".formatted(r.id(), r.room().number(),
    38	                        Formats.date(r.checkInDate()), Formats.date(r.checkOutDate())));
    39	            }
    40	            default -> {
    41	            }
    42	        }
    43	    }
    44	}
