     1	package br.com.marealta.notification;
     2	
     3	import java.util.ArrayList;
     4	import java.util.List;
     5	
     6	/** Entrega cada evento a todos os interessados; a falha de um não impede o aviso dos outros. */
     7	public class ReservationEvents {
     8	    private static final System.Logger LOG = System.getLogger(ReservationEvents.class.getName());
     9	
    10	    private final List<ReservationListener> listeners = new ArrayList<>();
    11	
    12	    public ReservationEvents(List<? extends ReservationListener> listeners) {
    13	        this.listeners.addAll(listeners);
    14	    }
    15	
    16	    public void publish(ReservationEvent event) {
    17	        for (ReservationListener listener : listeners) {
    18	            try {
    19	                listener.on(event);
    20	            } catch (RuntimeException e) {
    21	                LOG.log(System.Logger.Level.ERROR,
    22	                        "Falha ao avisar " + listener.getClass().getSimpleName(), e);
    23	            }
    24	        }
    25	    }
    26	}
