=== service/ReservationService.java
     1	package br.com.marealta.service;
     2	
     3	import br.com.marealta.domain.DomainException;
     4	import br.com.marealta.domain.ErrorCode;
     5	import br.com.marealta.domain.Receipt;
     6	import br.com.marealta.domain.Reservation;
     7	import br.com.marealta.domain.ReservationStatus;
     8	import br.com.marealta.domain.Room;
     9	import br.com.marealta.notification.ReservationEvent;
    10	import br.com.marealta.notification.ReservationEvents;
    11	
    12	import java.util.ArrayList;
    13	import java.util.List;
    14	import java.util.function.Function;
    15	
    16	public class ReservationService {
    17	    private final RoomCatalog rooms;
    18	    private final ReservationEvents events;
    19	    private final List<Reservation> reservations = new ArrayList<>();
    20	
    21	    public ReservationService(RoomCatalog rooms, ReservationEvents events) {
    22	        this.rooms = rooms;
    23	        this.events = events;
    24	    }
    25	
    26	    public synchronized Reservation create(NewReservation request) {
    27	        if (!request.checkOut().isAfter(request.checkIn())) {
    28	            throw new DomainException(ErrorCode.INVALID_REQUEST, "A saída deve ser depois da entrada");
    29	        }
    30	        if (request.guests() < 1) {
    31	            throw new DomainException(ErrorCode.INVALID_REQUEST, "É preciso pelo menos um hóspede");
    32	        }
    33	        Room room = rooms.get(request.roomNumber());
    34	        if (request.guests() > room.capacity()) {
    35	            throw new DomainException(ErrorCode.CAPACITY_EXCEEDED,
    36	                    "O quarto %d comporta no máximo %d hóspedes".formatted(room.number(), room.capacity()));
    37	        }
    38	        boolean taken = reservations.stream()
    39	                .filter(r -> r.room().equals(room) && r.status() != ReservationStatus.CANCELLED)
    40	                .anyMatch(r -> r.overlaps(request.checkIn(), request.checkOut()));
    41	        if (taken) {
    42	            throw new DomainException(ErrorCode.ROOM_UNAVAILABLE,
    43	                    "O quarto %d já está reservado em alguma das noites".formatted(room.number()));
    44	        }
    45	        Reservation reservation = new Reservation(reservations.size() + 1L, room, request.guestName(),
    46	                request.guestEmail(), request.guestCpf(), request.checkIn(), request.checkOut(),
    47	                request.guests(), request.ratePlan());
    48	        reservations.add(reservation);
    49	        return reservation;
    50	    }
    51	
    52	    public synchronized Reservation get(long id) {
    53	        if (id < 1 || id > reservations.size()) {
    54	            throw new DomainException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva não existe: " + id);
    55	        }
    56	        return reservations.get((int) id - 1);
    57	    }
    58	
    59	    public synchronized Reservation confirm(long id) {
    60	        Reservation reservation = get(id);
    61	        reservation.confirm();
    62	        events.publish(new ReservationEvent.Confirmed(reservation));
    63	        return reservation;
    64	    }
    65	
    66	    public synchronized Reservation cancel(long id) {
    67	        Reservation reservation = get(id);
    68	        ReservationStatus previous = reservation.status();
    69	        reservation.cancel();
    70	        events.publish(new ReservationEvent.Cancelled(reservation, previous));
    71	        return reservation;
    72	    }
    73	
    74	    public synchronized Reservation checkIn(long id) {
    75	        Reservation reservation = get(id);
    76	        reservation.checkIn();
    77	        return reservation;
    78	    }
    79	
    80	    public synchronized Receipt checkOut(long id) {
    81	        Reservation reservation = get(id);
    82	        reservation.checkOut();
    83	        return reservation.receipt();
    84	    }
    85	
    86	    public synchronized Receipt receipt(long id) {
    87	        return get(id).receipt();
    88	    }
    89	
    90	    /** Roda uma consulta (relatório) sobre as reservas sem que elas mudem no meio. */
    91	    public synchronized <T> T query(Function<List<Reservation>, T> query) {
    92	        return query.apply(List.copyOf(reservations));
    93	    }
    94	}
