    34	        if (request.guests() > room.capacity()) {
    35	            throw new DomainException(ErrorCode.CAPACITY_EXCEEDED,
    36	                    "O quarto %d comporta no máximo %d hóspedes".formatted(room.number(), room.capacity()));
    37	        }
    38	        boolean taken = reservations.stream()
    39	                .filter(r -> r.room().equals(room) && r.status() != ReservationStatus.CANCELLED)
    40	                .anyMatch(r -> r.overlaps(request.checkIn(), request.checkOut()));
    41	        if (taken) {
    42	            throw new DomainException(ErrorCode.ROOM_UNAVAILABLE,
    43	                    "O quarto %d já está reservado em alguma das noites".formatted(room.number()));
    44	        }
    45	        Reservation reservation = new Reservation(reservations.size() + 1L, room, request.guestName(),
    46	                request.guestEmail(), request.guestCpf(), request.checkIn(), request.checkOut(),
    47	                request.guests(), request.ratePlan());
    48	        reservations.add(reservation);
    49	        return reservation;
    50	    }
    51	
    52	    public synchronized Reservation get(long id) {
    53	        if (id < 1 || id > reservations.size()) {
    54	            throw new DomainException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva não existe: " + id);
    55	        }
    56	        return reservations.get((int) id - 1);
    57	    }
