    66	    public synchronized Reservation cancel(long id) {
    67	        Reservation reservation = get(id);
    68	        ReservationStatus previous = reservation.status();
    69	        reservation.cancel();
    70	        events.publish(new ReservationEvent.Cancelled(reservation, previous));
    71	        return reservation;
    72	    }
    73	
    74	    public synchronized Reservation checkIn(long id) {
    75	        Reservation reservation = get(id);
    76	        reservation.checkIn();
    77	        return reservation;
    78	    }
