    36	        this.ratePlan = ratePlan;
    37	        this.nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    38	        this.subtotal = checkIn.datesUntil(checkOut)
    39	                .map(room::priceOf)
    40	                .reduce(Formats.round(BigDecimal.ZERO), BigDecimal::add);
    41	        this.discount = ratePlan.discountOn(subtotal);
    42	        this.total = Formats.round(subtotal.subtract(discount));
