    19	    public String generate(YearMonth month) {
    20	        List<Reservation> kept = reservations.query(all -> all.stream()
    21	                .filter(r -> YearMonth.from(r.checkInDate()).equals(month) && r.amountKept().signum() > 0)
    22	                .sorted(Comparator.comparing(Reservation::checkInDate).thenComparingLong(Reservation::id))
